async function select(text){await body().evaluate((el,text)=>{el.focus();const walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode()){const at=n.textContent.indexOf(text);if(at>=0){const r=document.createRange();r.setStart(n,at);r.setEnd(n,at+text.length);const s=getSelection();s.removeAllRanges();s.addRange(r);return;}}throw Error('No text '+text);},text);await page.waitForTimeout(60);}
async function end(){await body().evaluate(el=>{el.focus();const r=document.createRange();r.selectNodeContents(el);r.collapse(false);getSelection().removeAllRanges();getSelection().addRange(r);});await page.waitForTimeout(60);const s=await snap(),last=s.blocks.filter(b=>['paragraph','heading'].includes(b.type)).at(-1);assert.equal(s.selection.to,last.to);}
async function download(item,name){await page.getByRole('button',{name:'File',exact:true}).click();let d;if(item==='Download Word (.docx)'){await page.getByRole('menuitem',{name:item,exact:true}).click();const trigger=page.locator('.export-ready').getByRole('link');await trigger.waitFor();[d]=await Promise.all([page.waitForEvent('download'),trigger.click()]);}else{[d]=await Promise.all([page.waitForEvent('download'),page.getByRole('menuitem',{name:item,exact:true}).click()]);}await d.saveAs(path.join(dir,name));return path.join(dir,name);}
const type=async text=>{await page.keyboard.insertText(text);await page.waitForTimeout(50);};
const clean=n=>{if(Array.isArray(n))return n.map(clean);if(n&&typeof n==='object')return Object.fromEntries(Object.entries(n).filter(([k])=>k!=='blockId').map(([k,v])=>[k,clean(v)]));return n;};
function texts(n){return (n.text||'')+(n.content||[]).map(texts).join('');}
function marked(n,token){if(n.text?.includes(token))return n;for(const x of n.content||[]){const found=marked(x,token);if(found)return found;}}
async function home(){await page.getByRole('button',{name:'Back to documents',exact:true}).click();await page.getByRole('button',{name:'New document',exact:true}).waitFor();}
